1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.clube.NivelClube;
4	import com.loja.checkout.cupom.Cupom;
5	import com.loja.checkout.dto.ItemRequest;
6	import com.loja.checkout.dto.ResumoRequest;
7	import com.loja.checkout.dto.ResumoResponse;
8	import com.loja.checkout.exception.CheckoutException;
9	import com.loja.checkout.modalidade.ModalidadeEntrega;
10	import com.loja.checkout.pagamento.FormaPagamento;
11	import com.loja.checkout.regiao.Regiao;
12	import org.springframework.stereotype.Service;
13	
14	import java.math.BigDecimal;
15	import java.math.RoundingMode;
16	import java.util.List;
17	
18	@Service
19	public class ResumoService {
20	
21	    public ResumoResponse calcular(ResumoRequest request) {
22	        validarItens(request.itens());
23	        NivelClube nivelClube = parseObrigatorio(NivelClube.class, request.nivelClube(), "NIVEL_CLUBE_INVALIDO");
24	        Regiao regiao = parseObrigatorio(Regiao.class, request.regiao(), "REGIAO_INVALIDA");
25	        ModalidadeEntrega modalidade = parseObrigatorio(ModalidadeEntrega.class, request.modalidadeEntrega(), "MODALIDADE_INVALIDA");
26	
27	        BigDecimal pesoTotal = pesoTotal(request.itens());
28	        if (!modalidade.disponivel(pesoTotal)) {
29	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
30	        }
31	
32	        Cupom cupom = null;
33	        BigDecimal subtotalProdutos = subtotalProdutos(request.itens());
34	        if (request.cupom() != null) {
35	            cupom = parseObrigatorio(Cupom.class, request.cupom(), "CUPOM_INVALIDO");
36	            if (!cupom.aplicavel(request.itens(), subtotalProdutos)) {
37	                throw new CheckoutException("CUPOM_NAO_APLICAVEL");
38	            }
39	        }
40	
41	        FormaPagamento formaPagamento = parseObrigatorio(FormaPagamento.class, request.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
42	        int parcelas = request.parcelas() == null ? 1 : request.parcelas();
43	        if (!formaPagamento.parcelasValidas(parcelas)) {
44	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
45	        }
46	
47	        BigDecimal frete = nivelClube.isentaFrete()
48	                ? Dinheiro.arredondar(BigDecimal.ZERO)
49	                : modalidade.frete(pesoTotal);
50	
51	        BigDecimal descontoCupom = cupom == null
52	                ? Dinheiro.arredondar(BigDecimal.ZERO)
53	                : cupom.desconto(request.itens(), subtotalProdutos, frete);
54	
55	        BigDecimal seguro = Dinheiro.arredondar(subtotalProdutos.multiply(regiao.percentualSeguro()));
56	
57	        BigDecimal totalPedido = Dinheiro.arredondar(
58	                subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro));
59	
60	        if (!formaPagamento.disponivel(totalPedido)) {
61	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
62	        }
63	
64	        BigDecimal totalFinal = formaPagamento.totalFinal(totalPedido, parcelas);
65	        BigDecimal ajustePagamento = Dinheiro.arredondar(totalFinal.subtract(totalPedido));
66	        BigDecimal valorParcela = Dinheiro.arredondar(
67	                totalFinal.divide(BigDecimal.valueOf(parcelas), 10, RoundingMode.HALF_EVEN));
68	
69	        BigDecimal creditoProximaCompra = nivelClube.credito(subtotalProdutos);
70	        boolean brinde = nivelClube.temBrinde(subtotalProdutos);
71	
72	        return new ResumoResponse(
73	                subtotalProdutos,
74	                descontoCupom,
75	                frete,
76	                modalidade.prazoDias(),
77	                seguro,
78	                ajustePagamento,
79	                totalFinal,
80	                parcelas,
81	                valorParcela,
82	                creditoProximaCompra,
83	                brinde
84	        );
85	    }
86	
87	    private void validarItens(List<ItemRequest> itens) {
88	        if (itens == null || itens.isEmpty()) {
89	            throw new CheckoutException("PEDIDO_INVALIDO");
90	        }
91	        for (ItemRequest item : itens) {
92	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
93	                    || item.quantidade() == null || item.quantidade() <= 0
94	                    || item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
95	                throw new CheckoutException("PEDIDO_INVALIDO");
96	            }
97	        }
98	    }
99	
100	    private BigDecimal subtotalProdutos(List<ItemRequest> itens) {
101	        BigDecimal subtotal = BigDecimal.ZERO;
102	        for (ItemRequest item : itens) {
103	            subtotal = subtotal.add(item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())));
104	        }
105	        return Dinheiro.arredondar(subtotal);
106	    }
107	
108	    private BigDecimal pesoTotal(List<ItemRequest> itens) {
109	        BigDecimal peso = BigDecimal.ZERO;
110	        for (ItemRequest item : itens) {
111	            peso = peso.add(item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())));
112	        }
113	        return peso;
114	    }
115	
116	    private <T extends Enum<T>> T parseObrigatorio(Class<T> tipo, String valor, String codigoErro) {
117	        if (valor == null) {
118	            throw new CheckoutException(codigoErro);
119	        }
120	        try {
121	            return Enum.valueOf(tipo, valor);
122	        } catch (IllegalArgumentException e) {
123	            throw new CheckoutException(codigoErro);
124	        }
125	    }
126	}
