6	import java.math.MathContext;
7	
8	public enum FormaPagamento {
9	
10	    PIX {
11	        @Override
12	        public boolean parcelasValidas(int parcelas) {
13	            return parcelas == 1;
14	        }
15	
16	        @Override
17	        public boolean disponivel(BigDecimal totalPedido) {
18	            return true;
19	        }
20	
21	        @Override
22	        public BigDecimal totalFinal(BigDecimal totalPedido, int parcelas) {
23	            return Dinheiro.arredondar(totalPedido.multiply(new BigDecimal("0.95")));
24	        }
25	    },
26	
27	    BOLETO {
28	        @Override
29	        public boolean parcelasValidas(int parcelas) {
30	            return parcelas == 1;
31	        }
32	
33	        @Override
34	        public boolean disponivel(BigDecimal totalPedido) {
35	            return totalPedido.compareTo(new BigDecimal("1000.00")) <= 0;
36	        }
37	
38	        @Override
39	        public BigDecimal totalFinal(BigDecimal totalPedido, int parcelas) {
40	            return Dinheiro.arredondar(totalPedido.add(new BigDecimal("3.49")));
41	        }
42	    },
43	
44	    CARTAO {
45	        @Override
46	        public boolean parcelasValidas(int parcelas) {
47	            return parcelas >= 1 && parcelas <= 12;
48	        }
49	
50	        @Override
51	        public boolean disponivel(BigDecimal totalPedido) {
52	            return true;
53	        }
54	
55	        @Override
56	        public BigDecimal totalFinal(BigDecimal totalPedido, int parcelas) {
57	            if (parcelas <= 3) {
58	                return Dinheiro.arredondar(totalPedido);
59	            }
60	            MathContext precisao = new MathContext(20);
61	            BigDecimal umMaisTaxa = BigDecimal.ONE.add(TAXA_MENSAL_CARTAO);
62	            BigDecimal umMaisTaxaElevado = umMaisTaxa.pow(parcelas, precisao);
63	            BigDecimal fatorDesconto = BigDecimal.ONE.subtract(
64	                    BigDecimal.ONE.divide(umMaisTaxaElevado, precisao));
65	            BigDecimal parcela = Dinheiro.arredondar(
66	                    totalPedido.multiply(TAXA_MENSAL_CARTAO).divide(fatorDesconto, precisao));
67	            return Dinheiro.arredondar(parcela.multiply(BigDecimal.valueOf(parcelas)));
68	        }
69	    };
70	
71	    private static final BigDecimal TAXA_MENSAL_CARTAO = new BigDecimal("0.0199");
72	
